let payload = msg;

// Nur weiterverarbeiten, wenn state == "RUN"
if (payload.state !== "RUN") return null;

// data-Feld parsen
let data;
try {
    data = JSON.parse(payload.data);
} catch (e) {
    return null;
}

// Nur primitive Werte für InfluxDB-Felder behalten
let fields = {};
for (let key in data) {
    if (["number", "string", "boolean"].includes(typeof data[key])) {
        fields[key] = data[key];
    }
}

// msg.payload als Objekt für InfluxDB
msg.measurement = "PipeWatch"; // Set it here for the node to see it
msg.payload = fields;          // The payload contains the actual data points
msg.tags = {                   // Optional: tags at the msg level
    device: payload.device || "unknown"
};

return msg;

let payload = msg.payload.packet.decoded.payload;

if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (e) {
        return null;
    }
}

return payload;
